package workbench.coroutines.l10

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.async
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotlinx.coroutines.test.TestScope
import kotlinx.coroutines.test.currentTime
import kotlinx.coroutines.test.runTest
import kotlinx.coroutines.withContext

@OptIn(ExperimentalCoroutinesApi::class)
fun main() {
    val realStart = System.nanoTime()
    fun real() = (System.nanoTime() - realStart) / 1_000_000
    // a rehearsal dinner on a fake clock: runTest is meant for tests, but a plain main can call it too
    runTest {
        fun TestScope.log(what: String) = println("virtual %5d ms (real %4d ms)  %s".format(currentTime, real(), what))
        launch {
            delay(1_000); log("soup simmered")
            delay(200); log("soup seasoned")
            delay(2_000); log("bread baked")
        }
        val roast = async {
            delay(3_000); log("roast cooked")
            delay(500); log("roast rested")
        }
        roast.await()
        log("await returned")
    }
    println("whole runTest took %d ms of real time".format(real()))

    runTest {
        val before = real()
        withContext(Dispatchers.Default) { delay(1_000) } // escapes the test scheduler
        println("withContext(Default) { delay(1_000) }: virtual $currentTime ms, real ${real() - before} ms")
    }
}

package workbench.coroutines.l10

import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotlinx.coroutines.test.UnconfinedTestDispatcher
import kotlinx.coroutines.test.advanceTimeBy
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.runCurrent
import kotlinx.coroutines.test.runTest

@OptIn(ExperimentalCoroutinesApi::class)
fun main() = runTest {
    // 1. runTest's default, StandardTestDispatcher: launch only queues the child
    val standard = mutableListOf<String>()
    launch { standard += "child ran" }
    standard += "after launch"
    runCurrent() // run what is due now
    println("StandardTestDispatcher:  $standard")

    // 2. UnconfinedTestDispatcher: the child starts at once, up to its first suspension
    val unconfined = mutableListOf<String>()
    launch(UnconfinedTestDispatcher(testScheduler)) { unconfined += "child ran" }
    unconfined += "after launch"
    println("UnconfinedTestDispatcher: $unconfined")

    // 3. backgroundScope: for work that never ends, such as a loop that reads the oven probe every second
    var polls = 0
    backgroundScope.launch { while (true) { delay(1_000); polls++ } }
    advanceTimeBy(5_500)
    println("polls after advanceTimeBy(5_500): $polls")
    advanceUntilIdle()
    println("polls after advanceUntilIdle(): $polls (background work doesn't keep it busy)")
    // when the test body ends, runTest cancels everything in backgroundScope
}

