class DinnerBudget {
    private final long limitCents;
    private long spentCents = 0;
    private final ReentrantLock lock = new ReentrantLock();

    DinnerBudget(long limitCents) { this.limitCents = limitCents; }

    boolean buy(String item) {
        long price = shop.priceOf(item);                  // 1. the slow call, outside the lock (blocks a thread)
        lock.lock();                                      // 2. blocks the thread while waiting
        try {
            if (spentCents + price > limitCents) return false;
            spentCents += price;                          // 3. check and spend together
            return true;
        } finally {
            lock.unlock();
        }
    }
}

kotlin.src:
class DinnerBudget(private val limitCents: Long) {
    private var spentCents = 0L
    private val mutex = Mutex()

    suspend fun buy(item: String): Boolean {
        val price = shop.priceOf(item)                    // 1. the slow call, outside the lock (suspends)
        return mutex.withLock {                           // 2. suspends while waiting, holds no thread
            if (spentCents + price > limitCents) return@withLock false
            spentCents += price                           // 3. check and spend together
            true
        }
    }
}

