fun `retries while the line is busy`() = runBlocking {
    var calls = 0
    val started = System.currentTimeMillis()
    val result = orders.orderWithRetry("rye") { calls++; if (calls < 4) throw IOException("busy") else "ticket 42" }
    assertThat(result).isEqualTo("ticket 42")
    assertThat(System.currentTimeMillis() - started).isBetween(1_350L, 1_600L)   // 200 + 400 + 800 = 1,400
}

