// Java equivalent of the shaky test: real sleeps, a timing window
@Test
void retriesWhileTheLineIsBusy() {
    AtomicInteger calls = new AtomicInteger();
    long started = System.currentTimeMillis();
    String result = orders.orderWithRetry("rye", () -> { if (calls.incrementAndGet() < 4) throw new UncheckedIOException(new IOException("busy")); return "ticket 42"; });
    assertThat(result).isEqualTo("ticket 42");
    assertThat(System.currentTimeMillis() - started).isBetween(1_350L, 1_600L);
}

