@Test
fun `waits 200, 400, then 800 ms between attempts`() = runTest {
    val at = mutableListOf<Long>()
    val result = orders.orderWithRetry("rye") {
        at += currentTime                                   // 1. record virtual ms per attempt
        if (at.size < 4) throw IOException("busy") else "ticket 42"
    }
    assertThat(result).isEqualTo("ticket 42")
    assertThat(at).containsExactly(0L, 200L, 600L, 1_400L)   // 2. exact, and instant
}

