// Java equivalent: Reactor's virtual time, if the orders are built on Reactor
@Test
void waitsBetweenAttempts() {
    StepVerifier.withVirtualTime(() -> orders.orderWithRetry("rye"))
        .expectSubscription()
        .thenAwait(Duration.ofMillis(1_400))             // 1. move the virtual clock
        .expectNext("ticket 42")                         // 2. exact, and instant
        .verifyComplete();
}

