class BakeryOrders(private val io: CoroutineDispatcher = Dispatchers.IO) {
    suspend fun <T> orderWithRetry(bread: String, call: suspend () -> T): T =
        withContext(io) { retryWithBackoff(times = 5, initialDelay = 200.milliseconds, maxDelay = 2.seconds) { call() } }
}

