@Test
void cancelDuringBackoffStopsRetries() {
    AtomicInteger calls = new AtomicInteger();
    StepVerifier.withVirtualTime(() -> orders.orderWithRetry("rye",
            Mono.<String>fromCallable(() -> { calls.incrementAndGet(); throw new IOException("busy"); })))
        .expectSubscription()
        .thenAwait(Duration.ofMillis(300))   // 4. attempts at 0 and 200 ms
        .thenCancel()
        .verify();
    assertThat(calls.get()).isEqualTo(2);
}

