class PlateCounts(private val kitchen: Kitchen) {
    private val counts = HashMap<String, Int>()
    private val mutex = Mutex()

    suspend fun serve(dish: String) {
        kitchen.plateUp(dish)                      // suspends: keep it outside the lock
        mutex.withLock { counts[dish] = (counts[dish] ?: 0) + 1 }
    }
}

@Test
fun `polls once a second`() = runTest {
    var polls = 0
    backgroundScope.launch { pollEvery(1.seconds) { polls++ } }   // never ends on its own
    advanceTimeBy(3_500)
    assertThat(polls).isEqualTo(3)
}

