// Java equivalent: a lock-free counter map, and Reactor virtual time for the poller
class PlateCounts {
    private final ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();

    void serve(String dish) {
        kitchen.plateUp(dish);                     // blocking: outside any lock
        counts.merge(dish, 1, Integer::sum);       // one atomic step
    }
}

@Test
void pollsOnceASecond() {
    StepVerifier.withVirtualTime(() -> Flux.interval(Duration.ofSeconds(1)).map(tick -> poll()))
        .expectSubscription()
        .thenAwait(Duration.ofMillis(3_500))
        .expectNextCount(3)
        .thenCancel()
        .verify();
}
